def LoadNPZ(path: pathlib.Path, allow_pickle: bool = False):
    try:
        return np.load(path, allow_pickle=allow_pickle)

    except:
        print("fail to load [{}]".format(path))
        return None


def GetAnalyticDataPaths(data_path: pathlib.Path,
                         cam_id: int,
                         start_time: int,
                         end_time: int,
                         suffix: str = "",
                         is_motion: bool = False) -> Tuple[pathlib.Path]:
    motion_tag = 'analytic_data'
    if is_motion:
        motion_tag = 'motion_raw_heatmap'

    raw_data_paths = tuple(
        data_path.glob("**/{}_{}_*[0-9]{}.npz".format(cam_id, motion_tag,
                                                      suffix)))

    if not raw_data_paths: return ()

    npz_end_time = map(lambda x: GetNPZEndTime(x.name, suffix), raw_data_paths)
    npz_end_time, raw_data_paths = tuple(
        zip(*((time, path)
              for time, path in sorted(zip(npz_end_time, raw_data_paths)))))

    lo_index = bisect.bisect_right(npz_end_time, start_time)
    hi_index = bisect.bisect_left(npz_end_time, end_time)

    raw_data_paths = raw_data_paths[lo_index:hi_index + 1]

    return raw_data_paths


def AdjustDataSize(data: np.array, axis: Union[List, int],
                   target_size: Union[List, int]) -> np.array:
    if type(axis) == int: axis = [axis]
    if type(target_size) == int: target_size = [target_size] * len(axis)

    assert len(axis) == len(
        target_size
    ), "Error: target_size should have same number with axis, or just give one int"

    result = data

    # Pad 0
    size_tuple = [(0, 0) for _ in range(len(data.shape))]
    for ax, sz in zip(axis, target_size):
        if data.shape[ax] < sz:
            size_tuple[ax] = (0, sz - data.shape[ax])
    result = np.pad(data, size_tuple, mode='constant', constant_values=0)

    # Remove redundant
    for ax, sz in zip(axis, target_size):
        if data.shape[ax] > sz:
            result = result.take(indices=range(0, sz), axis=ax)

    return result


def GetNPZEndTime(name: str, suffix: str) -> str:
    return int(re.search(r'([0-9]+){}\.npz$'.format(suffix), name).group(1))


def GetUnittestDataStartEndTime(name: str, suffix: str) -> int:
    return tuple(
        map(
            int,
            re.search(r'_([0-9]+)_([0-9]+)\.{}$'.format(suffix),
                      name).group(1, 2)))


def CvtTimestamp2Datetime(func):
    def wrapper(*args):
        time, delta_min = args
        if type(time) == int and time >= 0:
            time = datetime.fromtimestamp(time // 1000)
        elif type(time) == datetime:
            pass
        else:
            raise TypeError("Cannot convert given input time to datetime")

        return func(time, delta_min)

    return wrapper


def ToTimestampMS(func):
    def wrapper(*args, return_ts=False):
        res = func(*args)
        if return_ts:
            res = int(res.timestamp() * 1000)
        return res

    return wrapper


@ToTimestampMS
@CvtTimestamp2Datetime
def CeilTimeToNearestMin(time: Union[int, datetime],
                         delta_min: int) -> Union[int, datetime]:
    return time + (datetime.min - time) % timedelta(minutes=delta_min)


@ToTimestampMS
@CvtTimestamp2Datetime
def FloorTimeToNearestMin(time: Union[int, datetime],
                          delta_min: int) -> Union[int, datetime]:
    return time - (time - datetime.min) % timedelta(minutes=delta_min)


@ToTimestampMS
@CvtTimestamp2Datetime
def RoundTimeToNearestMin(time: Union[int, datetime],
                          delta_min: int) -> Union[int, datetime]:
    ceil_time = CeilTimeToNearestMin(time, delta_min)
    floor_time = FloorTimeToNearestMin(time, delta_min)

    if (time - floor_time) <= (ceil_time - time):
        return floor_time
    else:
        return ceil_time


def LimitMemUsage(soft, hard=0):  # In byte
    def IsValid(val):
        return val > 0 or val == resource.RLIM_INFINITY

    if hard == 0: hard = soft

    if not IsValid(soft) or not IsValid(hard):
        print("WARN: invalid limitation, settings not changed.")
        return

    resource.setrlimit(resource.RLIMIT_AS, (soft, hard))